# Based on analysis, the correct input-output mapping is:
# (0,0) -> in(0,0)
# (0,1) -> in(1,1)
# (0,2) -> in(0,4)
# (1,0) -> in(1,3)
# (1,1) -> in(2,2)
# (1,2) -> in(3,1)
# (2,0) -> in(4,0)
# (2,1) -> in(3,3)
# (2,2) -> in(4,4)

def antidiagonal_transform(g):
    """Transform 5x5 X-pattern to 3x3 output"""
    result = [[0]*3 for _ in range(3)]

    for r_out in range(3):
        for c_out in range(3):
            # Direct map based on observed positions
            if (r_out, c_out) == (0, 0):
                result[r_out][c_out] = g[0][0]
            elif (r_out, c_out) == (0, 1):
                result[r_out][c_out] = g[1][1]
            elif (r_out, c_out) == (0, 2):
                result[r_out][c_out] = g[0][4]
            elif (r_out, c_out) == (1, 0):
                result[r_out][c_out] = g[1][3]
            elif (r_out, c_out) == (1, 1):
                result[r_out][c_out] = g[2][2]
            elif (r_out, c_out) == (1, 2):
                result[r_out][c_out] = g[3][1]
            elif (r_out, c_out) == (2, 0):
                result[r_out][c_out] = g[4][0]
            elif (r_out, c_out) == (2, 1):
                result[r_out][c_out] = g[3][3]
            else:  # (2,2)
                result[r_out][c_out] = g[4][4]

    return result

# Test on demo input
input_grid = [
    [1, 0, 0, 0, 9],
    [0, 5, 0, 8, 0],
    [0, 0, 7, 0, 0],
    [0, 8, 0, 5, 0],
    [9, 0, 0, 0, 1]
]

output_grid = [
    [1, 5, 9],
    [8, 7, 8],
    [9, 5, 1]
]

result = antidiagonal_transform(input_grid)
print("Transformed:")
for row in result:
    print(row)
print("\nExpected:")
for row in output_grid:
    print(row)
print(f"\nCorrect: {result == output_grid}")

# Now let's find the general formula
print("\n\nFinding formula in terms of r_c_out, c_out:")

# Look at the pattern for in_row (row index needed):
print("\nin_row values:")
for r_out in range(3):
    row_vals = []
    for c_out in range(3):
        if (r_out, c_out) == (0, 0): row_vals.append(0)
        elif (r_out, c_out) == (0, 1): row_vals.append(1)
        elif (r_out, c_out) == (0, 2): row_vals.append(0)
        elif (r_out, c_out) == (1, 0): row_vals.append(1)
        elif (r_out, c_out) == (1, 1): row_vals.append(2)
        elif (r_out, c_out) == (1, 2): row_vals.append(3)
        elif (r_out, c_out) == (2, 0): row_vals.append(4)
        elif (r_out, c_out) == (2, 1): row_vals.append(3)
        else: row_vals.append(4)
    print(f"r_out={r_out}: {row_vals}")

# Looking at the in_row pattern:
# (0,0)=0, (0,1)=1, (0,2)=0
# (1,0)=1, (1,1)=2, (1,2)=3
# (2,0)=4, (2,1)=3, (2,2)=4

# in_row depends on BOTH r_out and c_out. 
# Let me express in_row as a function of c_out mostly, with r_out adjustment

print("\nin_col values:")
for r_out in range(3):
    col_vals = []
    for c_out in range(3):
        if (r_out, c_out) == (0, 0): col_vals.append(0)
        elif (r_out, c_out) == (0, 1): col_vals.append(1)
        elif (r_out, c_out) == (0, 2): col_vals.append(4)
        elif (r_out, c_out) == (1, 0): col_vals.append(3)
        elif (r_out, c_out) == (1, 1): col_vals.append(2)
        elif (r_out, c_out) == (1, 2): col_vals.append(1)
        elif (r_out, c_out) == (2, 0): col_vals.append(0)
        elif (r_out, c_out) == (2, 1): col_vals.append(3)
        else: col_vals.append(4)
    print(f"r_out={r_out}: {col_vals}")

# in_col pattern:
# r_out=0: (0,1,4) - anti-diag from top
# r_out=1: (3,2,1) - anti-diag from middle going down
# r_out=2: (0,3,4) - main-diag bottom

# For in_row:
# r_out=0: (0,1,0) - depends on c_out
# r_out=1: (1,2,3) - c_out increases by 1 each step from center
# r_out=2: (4,3,4) - symmetric

# Let me try to find formula:
# in_row = f(c_out, r_out)
# in_col = g(r_out, c_out)

print("\n\nDeriving formula:")
print("Observed in_row (for each r_out, as function of c_out):")
print("  r=0: [0,1,0]")
print("  r=1: [1,2,3]")  
print("  r=2: [4,3,4]")

# Try: in_row = r_out * 2 + c_out - in_col adjustment?
# For r=0: c=0->0, c=1->1, c=2->0 -- formula: c_out - 2*abs(c_out-1) ?
# For r=1: c=0->1, c=1->2, c=2->3 -- formula: 1 + c_out ?
# For r=2: c=0->4, c=1->3, c=2->4 -- formula: 4 - abs(c_out-1) ?

print("\nFormula attempts:")
for r_out in range(3):
    for c_out in range(3):
        # Try: in_row = (r_out + 1) * 2 - abs(2*r_out - c_out) - 1
        try_formula = (r_out + 1) * 2 - abs(2*r_out - c_out) - 1
        expected = [0,1,0][c_out] if r_out==0 else [1,2,3][c_out] if r_out==1 else [4,3,4][c_out]
        print(f"r={r_out},c={c_out}: try={try_formula}, expected={expected}, match={try_formula==expected}")

# Try a different formula: in_row = (4 - c_out) + (2*r_out - 1) * something?
print("\nTrying in_row = 4 - c_out mod r_out:")
for r_out in range(3):
    for c_out in range(3):
        try_formula = (4 - c_out) if r_out==0 else (1 + c_out) if r_out==1 else (4 - abs(c_out-1))
        expected = [0,1,0][c_out] if r_out==0 else [1,2,3][c_out] if r_out==1 else [4,3,4][c_out]
        print(f"r={r_out},c={c_out}: try={try_formula}, expected={expected}, match={try_formula==expected}")

# Test input:
test_input = [
    [7, 0, 0, 0, 5],
